) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Grup/role pengguna + level manajemen (1=STAFF .. 5=DIREKSI). Direferensikan sec_user_group & sec_group_permission.';
