DROP TABLE IF EXISTS `sec_module`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sec_module` (
  `id_module` int unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int unsigned DEFAULT NULL COMMENT 'NULL=modul induk | isi=sub-modul (mis. HPP di bawah INQUIRY)',
  `module_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode unik, mis. INQUIRY, HPP, MASTER',
  `module_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Label menu',
  `icon` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kelas ikon (Font Awesome) / emoji',
  `route_prefix` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Prefix route Laravel, mis. inquiry (utk mapping middleware)',
  `min_mgmt_level` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'Level manajemen MINIMUM utk akses (1=STAFF..5=DIREKSI). Report sensitif set tinggi',
  `is_reportable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=modul ini punya report (info tampilan)',
  `sort_order` smallint unsigned NOT NULL DEFAULT '999',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_module`) USING BTREE,
  UNIQUE KEY `uq_module_code` (`module_code`) USING BTREE,
  KEY `idx_module_parent` (`parent_id`) USING BTREE,
  CONSTRAINT `fk_module_parent` FOREIGN KEY (`parent_id`) REFERENCES `sec_module` (`id_module`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Modul bisnis = unit pemberian izin. module_code DIBUAT SAMA dengan kode modul sys_app_menu (SALES/PROC/INV/PROD/MDATA/FINACC/SETUP) agar izin & menu sinkron.';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sec_module` WRITE;
/*!40000 ALTER TABLE `sec_module` DISABLE KEYS */;
INSERT INTO `sec_module` VALUES (1,NULL,'SALES','Sales','fa-solid fa-file-invoice-dollar','sales',1,1,10,1,'2026-08-08 18:56:48','2026-08-08 18:56:48',NULL,NULL),(2,NULL,'PROC','Procurement','fa-solid fa-cart-shopping','procurement',1,0,50,1,'2026-08-08 18:56:48','2026-08-08 18:57:16',NULL,NULL),(3,NULL,'INV','Inventory','fa-solid fa-boxes-stacked','inventory',1,0,60,1,'2026-08-08 18:56:48','2026-08-08 18:57:16',NULL,NULL),(4,NULL,'PROD','Production','fa-solid fa-industry','production',1,1,40,1,'2026-08-08 18:56:48','2026-08-08 18:56:48',NULL,NULL),(5,NULL,'MDATA','Master Data','fa-solid fa-database','master',2,0,50,1,'2026-08-08 18:56:48','2026-08-08 18:56:48',NULL,NULL),(6,NULL,'FINACC','Finance & Accounting','fa-solid fa-sack-dollar','finance',3,1,60,1,'2026-08-08 18:56:48','2026-08-08 18:56:48',NULL,NULL),(9,NULL,'SETUP','Setup','fa-solid fa-gear','setup',5,0,99,1,'2026-08-08 18:56:48','2026-08-08 18:56:48',NULL,NULL),(13,NULL,'COSTING','Costing (HPP)','fa-solid fa-calculator','inquiry-costing',2,1,15,1,'2026-08-14 21:38:35','2026-08-14 21:38:35',NULL,NULL),(14,NULL,'HRM','Human Resources','fa-solid fa-users','hrm',2,1,45,1,'2026-08-18 23:53:40','2026-08-18 23:53:40',NULL,NULL);
