DROP TABLE IF EXISTS `sec_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sec_user` (
  `id_user` bigint unsigned NOT NULL AUTO_INCREMENT,
  `login` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Username login',
  `pswd` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hash password (bcrypt Laravel)',
  `default_password` text COLLATE utf8mb4_unicode_ci COMMENT 'Ciphertext Laravel Crypt (AES-256, key=APP_KEY). Password default terbaca oleh admin. Permanen, timpa saat reset.',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = user wajib ganti password saat login berikutnya (habis reset / user baru).',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'ex active varchar(1) -> tinyint',
  `is_admin` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ex priv_admin: superadmin bypass semua izin',
  `activation_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mfa` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Secret MFA (bila aktif)',
  `mfa_last_updated` timestamp NULL DEFAULT NULL,
  `pswd_last_updated` timestamp NULL DEFAULT NULL,
  `employee_id` bigint unsigned DEFAULT NULL COMMENT 'FK logis -> emp_employee (tm2mst)',
  `linked_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jenis entitas tertaut, mis. EMPLOYEE',
  `linked_id` bigint unsigned DEFAULT NULL COMMENT 'ID entitas master (lintas-DB, dijaga app)',
  `id_type` enum('nik','nrp') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `reg_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'customer|supplier|internal — hanya diisi dari self-registration',
  `id_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NIK (customer/supplier) atau NRP (internal) dari self-registration',
  `email_verified` tinyint(1) NOT NULL DEFAULT '0',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `wa_verified` tinyint(1) NOT NULL DEFAULT '0',
  `wa_verified_at` timestamp NULL DEFAULT NULL,
  `approval_status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `theme_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'navy',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_user`) USING BTREE,
  UNIQUE KEY `uq_user_login` (`login`) USING BTREE,
  KEY `idx_user_employee` (`employee_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Akun login. login=username unik, pswd=hash. Kolom pendaftaran: id_type/id_number (NIK/NRP), email_verified, wa_verified, approval_status, theme_code. linked_type/linked_id menaut ke customer/supplier. (Catatan: active vs is_active masih dobel — pilih satu; reg_type overlap dgn linked_type.)';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sec_user` WRITE;
