DROP TABLE IF EXISTS `sys_app_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_app_menu` (
  `id` int NOT NULL,
  `parent_id` int DEFAULT NULL,
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `label` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trans_key` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `menu_type` enum('module','group','item') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'item',
  `object_type` enum('form','grid','report','dashboard','link') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_kind` enum('app','php','html','url') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'app',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `required_object` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `status_code` enum('NOT_BUILT','READY_FOR_QC','LOCKED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_BUILT' COMMENT 'Kesiapan build (menu_type=item saja) -- lihat module_status_system di GLOBAL_RULES.yaml',
  `status_note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_updated_at` datetime DEFAULT NULL,
  `doc_slug` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Basis nama file docs/*.md /.yaml terkait, TANPA _tierN & ekstensi. File aktual = {doc_slug}_tier{n}.md, {doc_slug}_state.yaml, dst. Bisa sama antar >1 code (1 dok membahas >1 submodule).',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_parent` (`parent_id`,`sort_order`),
  KEY `idx_sys_app_menu_status` (`status_code`),
  CONSTRAINT `sys_app_menu_ibfk_1` FOREIGN KEY (`parent_id`) REFERENCES `sys_app_menu` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Menu dinamis (mega menu / sidebar / command palette) — LAYER TAMPILAN. Hierarki module->group->item; target+target_kind=eksekusi; required_object -> sec_module.module_code (kaitan hak akses).';
/*!40101 SET character_set_client = @saved_cs_client */;

