/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_support_tickets` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `ticket_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reporter` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('bug','feature_request','question') COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` enum('low','medium','high','urgent') COLLATE utf8mb4_unicode_ci DEFAULT 'medium',
  `subject` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `menu_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_version` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser_info` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('new','reviewing','in_progress','done','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'new',
  `assigned_to` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ticket_no` (`ticket_no`),
  KEY `idx_status` (`status`),
  KEY `idx_reporter` (`reporter`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tiket dukungan dari user ke tim pembuat aplikasi. type=bug/feature_request/question; status new..done/rejected; menu_code/app_version/browser_info = konteks otomatis utk reproduksi.';
