DROP TABLE IF EXISTS `sys_user_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user_menu` (
  `id_umenu` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'PK',
  `section` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Judul kelompok di dropdown (mis. "Pesan & info", "Akun"). Kosong/NULL = tanpa header (mis. tombol Keluar).',
  `code` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode unik stabil item, dipakai kode aplikasi (mis. UM_CHAT).',
  `label` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Teks yang tampil di menu.',
  `icon` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kelas ikon Font Awesome (mis. fa-solid fa-comment-dots).',
  `action_type` enum('drawer','modal','menu','url','lang','logout') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'url' COMMENT 'Jenis aksi saat diklik: drawer=buka panel geser | modal=buka pop-up | menu=buka objek di sys_app_menu | url=arahkan ke halaman | lang=ganti bahasa | logout=keluar.',
  `action_target` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sasaran aksi sesuai action_type: id drawer (chatDrawer) | id modal (mEdit) | code sys_app_menu (SET_USER) | URL/route (support.php) | login.html utk logout. NULL utk lang.',
  `badge_source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sumber angka badge di item: "chat" (sys_chat_*), "notif" (sys_notifications), atau NULL bila tak berbadge.',
  `is_danger` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=tampil merah/menonjol (mis. Keluar aplikasi).',
  `admin_only` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=hanya tampil untuk admin/berwenang (mis. Pengaturan/Setup). Tetap wajib dicek izin di server.',
  `sort_order` smallint unsigned NOT NULL DEFAULT '999' COMMENT 'Urutan tampil (kecil di atas).',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=tampil, 0=disembunyikan tanpa dihapus.',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_umenu`),
  UNIQUE KEY `uq_umenu_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Menu profil (dropdown avatar): chat, notifikasi, AI, edit profil, ubah password, setup, bahasa, keluar. Item & urutan diatur dari tabel ini.';
/*!40101 SET character_set_client = @saved_cs_client */;

